begin;
create extension if not exists pgcrypto;
create type public.workspace_role as enum ('owner','admin','member','guest');
create type public.card_priority as enum ('low','medium','high','urgent');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspaces (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 120), owner_id uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspace_members (workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role public.workspace_role not null default 'member', joined_at timestamptz not null default now(), primary key(workspace_id,user_id));
create table public.boards (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, title text not null check(length(title) between 1 and 160), description text not null default '', background text not null default 'coast', is_favorite boolean not null default false, is_template boolean not null default false, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.lists (id uuid primary key default gen_random_uuid(), board_id uuid not null references public.boards(id) on delete cascade, title text not null check(length(title) between 1 and 120), position numeric(20,8) not null, is_collapsed boolean not null default false, created_at timestamptz not null default now(), unique(board_id,position));
create table public.cards (id uuid primary key default gen_random_uuid(), board_id uuid not null references public.boards(id) on delete cascade, list_id uuid not null references public.lists(id) on delete cascade, title text not null check(length(title) between 1 and 240), description text not null default '', priority public.card_priority not null default 'medium', position numeric(20,8) not null, due_at timestamptz, start_at timestamptz, reminder_at timestamptz, completed boolean not null default false, checklist jsonb not null default '[]', custom_fields jsonb not null default '{}', dependencies jsonb not null default '[]', created_by uuid not null default auth.uid() references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(list_id,position));
create table public.labels (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null, color text not null default '#5f8dff', unique(workspace_id,name));
create table public.card_labels (card_id uuid not null references public.cards(id) on delete cascade, label_id uuid not null references public.labels(id) on delete cascade, primary key(card_id,label_id));
create table public.card_members (card_id uuid not null references public.cards(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, primary key(card_id,user_id));
create table public.checklists (id uuid primary key default gen_random_uuid(), card_id uuid not null references public.cards(id) on delete cascade, title text not null default 'Checklist', position numeric(20,8) not null);
create table public.checklist_items (id uuid primary key default gen_random_uuid(), checklist_id uuid not null references public.checklists(id) on delete cascade, text text not null, completed boolean not null default false, position numeric(20,8) not null, completed_by uuid references public.profiles(id), completed_at timestamptz);
create table public.comments (id uuid primary key default gen_random_uuid(), card_id uuid not null references public.cards(id) on delete cascade, author_id uuid not null default auth.uid() references public.profiles(id), body text not null check(length(body) between 1 and 10000), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.attachments (id uuid primary key default gen_random_uuid(), card_id uuid not null references public.cards(id) on delete cascade, uploaded_by uuid not null default auth.uid() references public.profiles(id), name text not null, storage_path text not null unique, mime_type text, size_bytes bigint not null default 0 check(size_bytes>=0), created_at timestamptz not null default now());
create table public.custom_field_definitions (id uuid primary key default gen_random_uuid(), board_id uuid not null references public.boards(id) on delete cascade, name text not null, field_type text not null check(field_type in ('text','number','date','select','checkbox')), options jsonb not null default '[]', position numeric(20,8) not null);
create table public.custom_field_values (card_id uuid not null references public.cards(id) on delete cascade, field_id uuid not null references public.custom_field_definitions(id) on delete cascade, value jsonb not null, primary key(card_id,field_id));
create table public.card_dependencies (card_id uuid not null references public.cards(id) on delete cascade, depends_on_card_id uuid not null references public.cards(id) on delete cascade, primary key(card_id,depends_on_card_id), check(card_id<>depends_on_card_id));
create table public.activity (id bigint generated always as identity primary key, board_id uuid not null references public.boards(id) on delete cascade, card_id uuid references public.cards(id) on delete cascade, actor_id uuid references public.profiles(id), action text not null, payload jsonb not null default '{}', created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, board_id uuid references public.boards(id) on delete cascade, card_id uuid references public.cards(id) on delete cascade, kind text not null, title text not null, read_at timestamptz, created_at timestamptz not null default now());
create table public.user_settings (user_id uuid primary key references public.profiles(id) on delete cascade, email_reminders boolean not null default true, reduced_motion boolean not null default false, timezone text not null default 'UTC', updated_at timestamptz not null default now());
create index boards_workspace_updated_idx on public.boards(workspace_id,updated_at desc); create index lists_board_position_idx on public.lists(board_id,position); create index cards_board_idx on public.cards(board_id); create index cards_list_position_idx on public.cards(list_id,position); create index cards_due_idx on public.cards(due_at) where completed=false; create index comments_card_created_idx on public.comments(card_id,created_at); create index activity_board_created_idx on public.activity(board_id,created_at desc); create index notifications_user_unread_idx on public.notifications(user_id,created_at desc) where read_at is null;
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create trigger touch_profiles before update on public.profiles for each row execute function public.touch_updated_at(); create trigger touch_workspaces before update on public.workspaces for each row execute function public.touch_updated_at(); create trigger touch_boards before update on public.boards for each row execute function public.touch_updated_at(); create trigger touch_cards before update on public.cards for each row execute function public.touch_updated_at();
create or replace function public.handle_new_user() returns trigger security definer set search_path=public language plpgsql as $$begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1))); insert into public.user_settings(user_id) values(new.id); return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.add_workspace_owner() returns trigger security definer set search_path=public language plpgsql as $$begin insert into public.workspace_members(workspace_id,user_id,role) values(new.id,new.owner_id,'owner'); return new;end$$;
create trigger workspace_owner after insert on public.workspaces for each row execute function public.add_workspace_owner();
create or replace function public.is_workspace_member(wid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from workspace_members where workspace_id=wid and user_id=auth.uid())$$;
create or replace function public.can_access_board(bid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from boards b join workspace_members m on m.workspace_id=b.workspace_id where b.id=bid and m.user_id=auth.uid())$$;
create or replace function public.card_board(cid uuid) returns uuid language sql stable security definer set search_path=public as $$select board_id from cards where id=cid$$;
create or replace function public.record_card_activity() returns trigger security definer set search_path=public language plpgsql as $$begin insert into activity(board_id,card_id,actor_id,action,payload) values(coalesce(new.board_id,old.board_id),coalesce(new.id,old.id),auth.uid(),tg_op,case when tg_op='DELETE' then jsonb_build_object('title',old.title) else jsonb_build_object('title',new.title) end); return coalesce(new,old);end$$;
create trigger card_activity after insert or update or delete on public.cards for each row execute function public.record_card_activity();
alter table public.profiles enable row level security; alter table public.workspaces enable row level security; alter table public.workspace_members enable row level security; alter table public.boards enable row level security; alter table public.lists enable row level security; alter table public.cards enable row level security; alter table public.labels enable row level security; alter table public.card_labels enable row level security; alter table public.card_members enable row level security; alter table public.checklists enable row level security; alter table public.checklist_items enable row level security; alter table public.comments enable row level security; alter table public.attachments enable row level security; alter table public.custom_field_definitions enable row level security; alter table public.custom_field_values enable row level security; alter table public.card_dependencies enable row level security; alter table public.activity enable row level security; alter table public.notifications enable row level security; alter table public.user_settings enable row level security;
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or exists(select 1 from workspace_members mine join workspace_members theirs using(workspace_id) where mine.user_id=auth.uid() and theirs.user_id=profiles.id)); create policy profiles_self on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy workspace_select on public.workspaces for select to authenticated using(public.is_workspace_member(id)); create policy workspace_insert on public.workspaces for insert to authenticated with check(owner_id=auth.uid()); create policy workspace_update on public.workspaces for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid()); create policy workspace_delete on public.workspaces for delete to authenticated using(owner_id=auth.uid());
create policy members_select on public.workspace_members for select to authenticated using(user_id=auth.uid() or public.is_workspace_member(workspace_id)); create policy members_manage on public.workspace_members for all to authenticated using(exists(select 1 from workspaces w where w.id=workspace_id and w.owner_id=auth.uid())) with check(exists(select 1 from workspaces w where w.id=workspace_id and w.owner_id=auth.uid()));
create policy boards_member on public.boards for all to authenticated using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id) and created_by=auth.uid());
create policy lists_member on public.lists for all to authenticated using(public.can_access_board(board_id)) with check(public.can_access_board(board_id)); create policy cards_member on public.cards for all to authenticated using(public.can_access_board(board_id)) with check(public.can_access_board(board_id)); create policy labels_member on public.labels for all to authenticated using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy card_labels_member on public.card_labels for all to authenticated using(public.can_access_board(public.card_board(card_id))) with check(public.can_access_board(public.card_board(card_id))); create policy card_members_member on public.card_members for all to authenticated using(public.can_access_board(public.card_board(card_id))) with check(public.can_access_board(public.card_board(card_id)));
create policy checklist_member on public.checklists for all to authenticated using(public.can_access_board(public.card_board(card_id))) with check(public.can_access_board(public.card_board(card_id))); create policy checklist_items_member on public.checklist_items for all to authenticated using(exists(select 1 from checklists c where c.id=checklist_id and public.can_access_board(public.card_board(c.card_id)))) with check(exists(select 1 from checklists c where c.id=checklist_id and public.can_access_board(public.card_board(c.card_id))));
create policy comments_member on public.comments for select to authenticated using(public.can_access_board(public.card_board(card_id))); create policy comments_insert on public.comments for insert to authenticated with check(author_id=auth.uid() and public.can_access_board(public.card_board(card_id))); create policy comments_update on public.comments for update to authenticated using(author_id=auth.uid()) with check(author_id=auth.uid()); create policy comments_delete on public.comments for delete to authenticated using(author_id=auth.uid());
create policy attachments_member on public.attachments for select to authenticated using(public.can_access_board(public.card_board(card_id))); create policy attachments_write on public.attachments for insert to authenticated with check(uploaded_by=auth.uid() and public.can_access_board(public.card_board(card_id))); create policy attachments_delete on public.attachments for delete to authenticated using(uploaded_by=auth.uid());
create policy fields_member on public.custom_field_definitions for all to authenticated using(public.can_access_board(board_id)) with check(public.can_access_board(board_id)); create policy values_member on public.custom_field_values for all to authenticated using(public.can_access_board(public.card_board(card_id))) with check(public.can_access_board(public.card_board(card_id))); create policy deps_member on public.card_dependencies for all to authenticated using(public.can_access_board(public.card_board(card_id))) with check(public.can_access_board(public.card_board(card_id))); create policy activity_member on public.activity for select to authenticated using(public.can_access_board(board_id)); create policy notifications_self on public.notifications for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy settings_self on public.user_settings for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('attachments','attachments',false,26214400,array['image/png','image/jpeg','image/webp','application/pdf','text/plain']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy attachment_storage_select on storage.objects for select to authenticated using(bucket_id='attachments' and public.can_access_board(public.card_board((storage.foldername(name))[1]::uuid))); create policy attachment_storage_insert on storage.objects for insert to authenticated with check(bucket_id='attachments' and public.can_access_board(public.card_board((storage.foldername(name))[1]::uuid))); create policy attachment_storage_delete on storage.objects for delete to authenticated using(bucket_id='attachments' and owner_id=auth.uid()::text);
do $$begin alter publication supabase_realtime add table public.cards; exception when duplicate_object then null; end$$; do $$begin alter publication supabase_realtime add table public.comments; exception when duplicate_object then null; end$$; do $$begin alter publication supabase_realtime add table public.notifications; exception when duplicate_object then null; end$$;
commit;
